<section class="page-heading"><div><p class="eyebrow">Sales</p><h1>Sales History</h1><p class="subtitle">Review completed transactions.</p></div><a class="button" href="<?= site_url('sales/new') ?>">Record Sale</a></section><?php if(session()->getFlashdata('message')): ?><p class="success"><?= esc(session()->getFlashdata('message')) ?></p><?php endif; ?><div class="table-card"><div class="table-scroll"><table><thead><tr><th>ID</th><th>Product</th><th>Customer</th><th>Staff</th><th>Qty</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($sales as $s): ?><tr><td data-label="ID"><?= esc($s['id']) ?></td><td data-label="Product"><?= esc($s['product_name']) ?></td><td data-label="Customer"><?= esc($s['customer_name'] ?: 'Walk-in') ?></td><td data-label="Staff"><?= esc($s['staff_name']) ?></td><td data-label="Qty"><?= esc($s['quantity']) ?></td><td data-label="Total">₱<?= number_format((float)$s['total_price'],2) ?></td><td data-label="Date"><?= esc($s['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
